FROM superhero
WHERE race_id = 24 AND height_cm IS NOT NULL AND height_cm != 0;

WITH PatientsWithLab AS (
  SELECT DISTINCT ID FROM Laboratory
),
NormalPlateletPatients AS (
  SELECT DISTINCT ID FROM Laboratory WHERE PLT > 100 AND PLT < 400
),
TargetPatients AS (
  SELECT ID FROM Patient WHERE Diagnosis IN ('RA, SJS', 'SJS, RA', 'RA,SJS')
)
SELECT
  (SELECT COUNT(*) FROM TargetPatients WHERE ID IN (SELECT ID FROM NormalPlateletPatients)) AS PatientsWithNormalPlatelets,
  (SELECT COUNT(*) FROM TargetPatients WHERE ID NOT IN (SELECT ID FROM NormalPlateletPatients)) AS PatientsWithoutNormalPlatelets
;

